import{_ as s,o as t,c as i,a6 as r}from"./chunks/framework.DIp0zHSV.js";const u=JSON.parse(`{"title":"Users & Devices","description":"The Users & Devices tab of the LCARdS Config Panel: this browser's device name and id, the users and devices with their own settings, and how device, user and global settings combine.","frontmatter":{"description":"The Users & Devices tab of the LCARdS Config Panel: this browser's device name and id, the users and devices with their own settings, and how device, user and global settings combine.","moved_anchors":{"current-session":"/configuration/users-devices#this-session","users-admin-only":"/configuration/users-devices#users-with-scoped-settings","devices-admin-only":"/configuration/users-devices#registered-devices"}},"headers":[],"relativePath":"configuration/users-devices.md","filePath":"configuration/users-devices.md","lastUpdated":1794184759000}`),o={name:"configuration/users-devices.md"};function a(n,e,d,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="users-devices" tabindex="-1">Users &amp; Devices <a class="header-anchor" href="#users-devices" aria-label="Permalink to &quot;Users &amp; Devices&quot;">​</a></h1><p><strong>The Users &amp; Devices tab of LCARdS Config shows who this browser is to LCARdS, and lets administrators see and tidy every user and device that has its own settings.</strong></p><ul><li>Every browser gets a device record: a stable id and a display name. Device names are what <a href="./ha-actions.html#targeting">targeted actions</a> and per-device settings use.</li><li>Everyone sees <strong>This Session</strong>. Home Assistant administrators also see <strong>Users with Scoped Settings</strong> and <strong>Registered Devices</strong>.</li><li>The settings themselves are changed in their own tabs (Sounds, Connectivity, Theme Studio &gt; Token Overrides); this tab manages the records.</li></ul><hr><h2 id="this-session" tabindex="-1">This Session <a class="header-anchor" href="#this-session" aria-label="Permalink to &quot;This Session&quot;">​</a></h2><p><strong>Your logged-in user and this browser&#39;s device record.</strong> Use it to name the browser, or to find its id for an action.</p><ul><li>Click the pencil next to <strong>Display Name</strong> to rename this device; Enter saves.</li><li>A new device is named after its browser and system (<code>Chrome-Android</code>, <code>Safari-iPhone</code>) until you rename it.</li><li>A device can be named from its address: add <code>?lcards_device=&lt;name&gt;</code>, for example <code>http://homeassistant.local:8123/?lcards_device=Kitchen%20Tablet</code>. The name applies on every load with it, over a name set before. Handy for kiosk bookmarks.</li><li><code>window.lcards.targeting.getMyIds()</code> in the browser console returns this device&#39;s id and your user id.</li></ul><table tabindex="0"><thead><tr><th>Detail</th><th>Description</th></tr></thead><tbody><tr><td><strong>Logged-in User</strong></td><td>Your Home Assistant user&#39;s name</td></tr><tr><td><strong>User ID</strong></td><td>Your Home Assistant user id, as <code>target_user_ids</code> takes it</td></tr><tr><td><strong>Device ID</strong></td><td>A stable id kept in this browser&#39;s <code>localStorage</code> (<code>lcards_device_id</code>). It survives reloads and logins in the same browser profile; clearing the site&#39;s data gives a new one</td></tr><tr><td><strong>Display Name</strong></td><td>The name for this browser. Editable by any user</td></tr><tr><td><strong>Last Seen</strong></td><td>When this device last checked in with the integration</td></tr><tr><td><strong>User Agent</strong></td><td>The browser and system string recorded for it</td></tr></tbody></table><hr><h2 id="users-with-scoped-settings" tabindex="-1">Users with Scoped Settings <a class="header-anchor" href="#users-with-scoped-settings" aria-label="Permalink to &quot;Users with Scoped Settings&quot;">​</a></h2><p><strong>Administrators only: every Home Assistant user with at least one setting of their own.</strong></p><ul><li>Each row shows the user&#39;s name (from Home Assistant), their id and the stored keys.</li><li><strong>Clear all overrides for this user</strong> deletes that user&#39;s own settings after a confirmation; they then get the device or global values. Device records and global settings are not touched.</li></ul><hr><h2 id="registered-devices" tabindex="-1">Registered Devices <a class="header-anchor" href="#registered-devices" aria-label="Permalink to &quot;Registered Devices&quot;">​</a></h2><p><strong>Administrators only: every browser that has registered with the integration, with its name, id and last check-in.</strong></p><ul><li><strong>Rename device</strong> edits the display name in place.</li><li><strong>Remove device record</strong> deletes the record and the settings stored for that device, after a confirmation. A browser that opens Home Assistant again registers again, with the same id.</li></ul><hr><h2 id="how-scoped-settings-work" tabindex="-1">How scoped settings work <a class="header-anchor" href="#how-scoped-settings-work" aria-label="Permalink to &quot;How scoped settings work&quot;">​</a></h2><p><strong>A setting that can differ per user or device takes the first value it finds: the device&#39;s, then the user&#39;s, then the global one.</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Device  →  User  →  Global  →  Built-in default (or the helper)</span></span></code></pre></div><ul><li><strong>Device</strong> settings apply to whoever is logged in on that browser.</li><li><strong>User</strong> settings apply to one Home Assistant user on every device.</li><li><strong>Global</strong> is the installation-wide value everyone shares.</li><li>Today these settings can be scoped: <a href="./sounds.html#per-user-per-device-overrides">sounds</a> (master switch, volume, scheme and per-event sounds), the <a href="./connectivity.html#scope-and-per-device-overrides">connection overlay</a>, and theme token overrides (Theme Studio &gt; Token Overrides).</li></ul><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./ha-actions.html#targeting">Home Assistant Actions: targeting</a>: send an <code>lcards.*</code> action to some devices or users only</li><li><a href="./sounds.html">Sound Configuration</a>: per-user and per-device sound settings</li><li><a href="./connectivity.html">Connectivity</a>: per-user and per-device connection overlay settings</li><li><a href="./../architecture/subsystems/scoped-settings.html">Scoped Settings Service</a>: developer reference for the storage behind this tab</li></ul>',24)])])}const v=s(o,[["render",a]]);export{u as __pageData,v as default};
